  if(name==="get_installation"){const p=a.profile||"default", map={default:{command:DATA.installation.default_command,members:DATA.installation.profiles.core},core:{command:DATA.installation.profile_commands.core,members:DATA.installation.profiles.core},ai:{command:DATA.installation.profile_commands.ai,members:DATA.installation.profiles.ai},quality:{command:DATA.installation.profile_commands.quality,members:DATA.installation.profiles.quality},showcases:{command:DATA.installation.profile_commands.showcases,members:DATA.installation.profiles.showcases},operating:{command:DATA.installation.profile_commands.operating,members:DATA.installation.profiles.operating},all:{command:DATA.installation.all_command,members:[...new Set(Object.values(DATA.installation.profiles).flat())]}};return map[p]?good({profile:p,command:map[p].command,members:map[p].members,execution:"inert guidance; this server never executes installation commands"}):bad("profile must be default, core, ai, quality, showcases, operating, or all")}
